Translate the following GNU C++11 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <cstdio>
#include <vector>
#include <algorithm>
#include <cmath>

using namespace std;

long long v;
vector<long long> cand(17);

int recursive(int index, long long value) {
    value = abs(value);
    if (index == 0) {
        return static_cast<int>(value);
    }
    int quotient1 = static_cast<int>(value / cand[index]);
    int quotient2 = quotient1 + 1;
    int option1 = quotient1 * (index + 1) + recursive(index - 1, value - quotient1 * cand[index]);
    int option2 = quotient2 * (index + 1) + recursive(index - 1, value - quotient2 * cand[index]);
    return min(option1, option2);
}

int main() {
    scanf("%lld", &v);
    cand[0] = 1;
    for (int i = 1; i < 17; ++i) {
        cand[i] = cand[i - 1] * 10 + 1;
    }
    printf("%d\n", recursive(16, v));
    return 0;
}
